-- Full-body rewrite of the page_version, same technique as V43/V44/V45 —
-- everything else (QrScan, onChangeFill, disabled auto-fill fields, Confirm
-- button) is carried over unchanged.

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "slug": "aria:parking-scan", "title": "Parking-Bay Scan", "status": "published", "version": 1, "roles": ["ParkingSecurity", "Dispatch", "Manager", "TenantAdmin"], "dataSources": [], "streams": [], "entity": "ParkingBayEntry", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Scan / Select Gate-Pass", "span": 12, "subtitle": "Tap Scan to use the camera, or pick the Gate Pass # from the list — vehicle, flow and loading context fill in automatically.", "children": [{"kind": "QrScan", "label": "Tap to Scan", "targetField": "gpNumber", "manualFallback": true}, {"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass #", "type": "select", "required": true, "placeholder": "Scan above or select Gate Pass #", "optionsSource": {"type": "datasource", "spec": {"type": "entity", "entity": "GatePass", "joins": [{"entity": "WorkflowInstance", "as": "wi", "on": "gate_pass.workflow_instance_id = wi.id"}], "filter": {"and": [{"field": "wi.assigned_role", "op": "eq", "value": "ParkingSecurity"}, {"field": "wi.status", "op": "eq", "value": "OPEN"}]}, "select": ["id", "gp_number"], "sort": [{"field": "gp_number", "dir": "desc"}]}, "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicleNo": "vehicle_no", "flowVariantCode": "flow_variant_code", "loadingType": "loading_type", "instanceId": "workflow_instance_id"}, "scannable": true, "freeSolo": true}, {"name": "vehicleNo", "label": "Vehicle Number", "type": "text", "disabled": true}, {"name": "flowVariantCode", "label": "Flow Variant", "type": "text", "disabled": true}, {"name": "loadingType", "label": "Loading Type", "type": "text", "disabled": true}, {"name": "instanceId", "label": "Workflow Instance", "type": "text", "disabled": true}]}}]}, {"kind": "Section", "span": 12, "children": [{"kind": "WorkflowActionButton", "action": "workflow.transition", "label": "Confirm